// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFeeVal, uint16 feeRateVal, uint128 vBase, uint128 vNft) public {
        vm.assume(feeRateVal <= 5_000);
        vm.assume(vNft > vBase); // any admissible reserves; keep wide
        c.initialize(address(0), address(0), vBase, vNft, changeFeeVal, feeRateVal, bytes32(0), false, false);
        // General rule: with native-ETH base token, flashFee must be changeFee * 1e14,
        // and changeFee is initialized from the _changeFee argument.
        assertTrue(c.flashFee(address(0), 0) == uint256(changeFeeVal) * 1e14);
    }
}
